{!REQUIRESCRIPT("/soap/ajax/30.0/connection.js")} 
{!REQUIRESCRIPT("/soap/ajax/30.0/apex.js")} 
var custSycDate = "{!Case.SMS_Customer_Sync_Date__c}";
var ordSycDate = "{!Case.SMS_Order_Sync_Date__c}";
if(custSycDate == '' || ordSycDate == ''){
	var conf = confirm("Click OK to confirm Sync to SMS");
	try{
		if(conf == true){ 
		var casId= "{!Case.Id}";
		var a = sforce.apex.execute("SITADIntegration","callSMSSync",{caseId:casId});
    alert(a);
		}
	}catch(e){ 
		alert("Something went worng. Please try after some time\n\n"+(e.message||e)); 
	}
}else if(custSycDate != '' && ordSycDate != ''){
	alert('Both Customer Account & Case are allready Synced');
}
